/**
 * useCompletion Hook - Layer 1 (Headless)
 *
 * Single text completion with streaming support.
 */
import { useCallback, useRef, useState } from "react";
import { createError, toError } from "../../errors/veryfront-error.js";
import { csrfMutationHeaders } from "../../security/csrf/browser-mutation-headers.js";
/**
 * useCompletion hook for single text generation
 */
export function useCompletion(options) {
    const [completion, setCompletion] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const abortControllerRef = useRef(null);
    const complete = useCallback(async (prompt) => {
        setIsLoading(true);
        setError(null);
        setCompletion("");
        const abortController = new AbortController();
        abortControllerRef.current = abortController;
        try {
            const response = await fetch(options.api, {
                method: "POST",
                // CSRF is enforced in every environment, local development included,
                // so this POST has to echo the configured CSRF cookie the document
                // response issued or the server answers 403. A caller that set the
                // header itself through `options.headers` keeps its own value.
                headers: csrfMutationHeaders(options.api, {
                    headers: {
                        "Content-Type": "application/json",
                        ...options.headers,
                    },
                }),
                body: JSON.stringify({ prompt, ...options.body }),
                signal: abortController.signal,
            });
            if (!response.ok) {
                throw toError(createError({
                    type: "agent",
                    message: `API error: ${response.status}`,
                }));
            }
            options.onResponse?.(response);
            const reader = response.body?.getReader();
            if (!reader)
                return;
            const decoder = new TextDecoder();
            let accumulatedText = "";
            while (true) {
                const { done, value } = await reader.read();
                if (done)
                    break;
                accumulatedText += decoder.decode(value, { stream: true });
                setCompletion(accumulatedText);
            }
            options.onFinish?.(accumulatedText);
        }
        catch (err) {
            if (err instanceof Error && err.name === "AbortError")
                return;
            const nextError = err instanceof Error ? err : new Error(String(err));
            setError(nextError);
            options.onError?.(nextError);
        }
        finally {
            setIsLoading(false);
            abortControllerRef.current = null;
        }
    }, [options]);
    const stop = useCallback(() => {
        abortControllerRef.current?.abort();
        abortControllerRef.current = null;
        setIsLoading(false);
    }, []);
    return {
        completion,
        isLoading,
        error,
        complete,
        stop,
        setCompletion,
    };
}
